update public.diseases set
  is_stub=false, name='Akut vesekárosodás', specialty='Nefrológia-urológia', abbrev='AKI', aliases='{"AKI","Akut veseelégtelenség"}',
  score_ids='{}', ekg_ids='{"hyperk"}', body='{"brief_what": "A vesefunkció órák–napok alatti hirtelen romlása (kreatinin-emelkedés és/vagy vizeletürítés csökkenése); gyakran reverzibilis, ha az okot időben kezelik.", "brief_why": "Az APN a rizikóbetegek felismerésével, a folyadék- és gyógyszerelési szempontok követésével és a vörös zászlók jelzésével csökkentheti a szövődményeket.", "when": ["Csökkenő vizeletmennyiség", "Emelkedő kreatinin/karbamid", "Volumenhiány (hányás, hasmenés, vérzés, sepsis)", "Nefrotoxikus gyógyszer vagy kontrasztanyag expozíció"], "examine": ["Volumenstátusz (turgor, nyálkahártyák, vérnyomás, JVP)", "Diurézis/folyadékmérleg", "Húgyúti obstrukció jelei (telt hólyag)", "Sepsis vagy szívelégtelenség jelei"], "labs": "Kreatinin, karbamid, ionok (különösen kálium), sav-bázis, vérkép; vizeletvizsgálat. A KDIGO stádiumbeosztás a kreatinin-emelkedés és a diurézis alapján.", "ekg": "Hyperkalaemia gyanúja esetén sürgősen (magas T-hullám, széles QRS).", "imaging": "Vese-ultrahang posztrenalis ok (obstrukció) kizárására.", "scores": "KDIGO AKI-stádium (1–3).", "red_flags": ["Hyperkalaemia (EKG-eltéréssel)", "Anuria / gyorsan romló funkció", "Folyadéktúlterhelés, tüdőoedema", "Súlyos metabolikus acidosis", "Uraemiás tünetek (tudatzavar, pericarditis)"], "apn_focus": ["Rizikóbetegek azonosítása és a vesefunkció követése", "Folyadékstátusz és -mérleg gondos megítélése", "Nefrotoxikus gyógyszerek és kontraszt kerülése/felülvizsgálata", "Hyperkalaemia és a dialízis-indikációk vörös zászlóinak felismerése"], "treatment": ["Ok kezelése (volumenpótlás vagy -megvonás a státusz szerint; sepsis/ obstrukció ellátása)", "Nefrotoxinok elhagyása, gyógyszeradagok veseműködéshez igazítása (orvosi rendelés szerint)", "Elektroliteltérések, különösen hyperkalaemia kezelése protokoll szerint", "Súlyos/refrakter esetben vesepótló kezelés mérlegelése"], "followup": ["Kreatinin, ionok és diurézis ismételt követése", "Gyógyszerelés újraértékelése", "A kiváltó ok rendezésének ellenőrzése", "Krónikus vesebetegséggé progresszió szűrése"], "source_name": "KDIGO AKI 2012 (és aktuális frissítések)", "source_url": "https://kdigo.org", "version": "1.0", "updated": "2026-08-24", "evidence": "Guideline-alapú (KDIGO)"}'::jsonb,
  epidemiology='Kórházi betegek gyakori szövődménye; rontja a mortalitást és növeli a krónikus vesebetegség kockázatát. Rizikó: idős kor, CKD, sepsis, nagy műtét, nefrotoxinok.', pathophysiology='Prerenalis (hypoperfúzió), renalis (parenchyma-károsodás, pl. akut tubuláris nekrózis) vagy posztrenalis (obstrukció) mechanizmus → csökkent GFR, salakanyag-retenció, folyadék- és elektrolitzavar.',
  ddx='[{"name": "Krónikus vesebetegség", "slug": "kronikus_vesebetegseg"}, {"name": "Hypovolaemia / dehidráció", "slug": "hypovolaemia_dehidracio"}, {"name": "Sepsis", "slug": "sepsis"}, {"name": "Szívelégtelenség", "slug": "szivelegtelenseg"}, {"name": "Húgyúti obstrukció", "slug": "hugyuti_obstrukcio"}, {"name": "Hyperkalaemia", "slug": "hyperkalaemia"}]'::jsonb,
  apn_approach='{"anamnesis": "Folyadékvesztés/-bevitel, vizeletürítés változása, gyógyszerek (NSAID, RAAS-gátló, diuretikum), kontraszt, ismert vesebetegség.", "physical": "Volumenstátusz, vérnyomás, diurézis, telt hólyag, sepsis vagy szívelégtelenség jelei.", "data": "Kreatinin-trend, ionok (kálium!), sav-bázis, vizelet; vese-UH obstrukció kizárására; KDIGO-stádium.", "thinking": "Pre-/renalis/posztrenalis ok elkülönítése; reverzibilis tényezők és a sürgős dialízis-indikációk gyors felmérése.", "consultation": "Stádium-emelkedés, hyperkalaemia, oliguria/anuria, tisztázatlan ok orvosi/nefrológiai konzultációt igényel.", "escalation": "Életveszélyes hyperkalaemia, refrakter folyadéktúlterhelés, súlyos acidosis, uraemiás szövődmény sürgős ellátást igényel."}'::jsonb, evidence_levels='{"guideline","evidence"}', validation_status='review_pending',
  block_sources='{"labor": "KDIGO AKI", "ekg": "Hyperkalaemia EKG-jelei", "kezeles": "KDIGO AKI + helyi protokoll"}'::jsonb, version='1.0', review_on='2027-08-01'
where slug='akut_vesekarosodas';
